void require(bool b,const char* s){if(!b)throw std::runtime_error(s);}QString newId(){return QUuid::createUuid().toString(QUuid::WithoutBraces);}QString sha256(const QByteArray& b){return QString::fromLatin1(underlay::digest(b).toHex());}
namespace {
QByteArray encode(const QJsonObject& s){auto b=QJsonDocument(s).toJson(QJsonDocument::Compact);auto out=QJsonDocument(QJsonObject{{"payload",s},{"sha256",sha256(b)}}).toJson(QJsonDocument::Compact);require(out.size()<=Store::MaxBytes,"product-store-full");return out;}
// D2 page-turn latency: every page's ink layer (and every stroke batch) opens this store, and a full read
// re-parses and re-hashes the whole book's features (MBs). A validated state is remembered per directory with the
// file's identity (device, inode, size, mtime, ctime) and binding. Commits replace the file by atomic rename (new
// inode) and any in-place change moves ctime, so an identical identity under the store's exclusive lock means the
// bytes are the ones already validated.
struct Remembered {dev_t dev{};ino_t ino{};off_t size{};long long mtimS{},mtimN{},ctimS{},ctimN{};QJsonObject binding,state;quint64 age{};bool notesNormalized{};};
std::mutex rememberedMutex;std::map<std::string,Remembered> remembered;quint64 cacheAge{},cacheHits{},cacheMisses{};
qint64 cachedBytes(){qint64 n=0;for(const auto& entry:remembered)n+=entry.second.size;return n;}
bool identity(const std::filesystem::path& p,Remembered& r){struct stat st{};if(::lstat(p.c_str(),&st)||!S_ISREG(st.st_mode)||st.st_uid!=getuid()||st.st_nlink!=1||(st.st_mode&0777)!=0600||st.st_size<=0||st.st_size>Store::MaxBytes)return false;
 r.dev=st.st_dev;r.ino=st.st_ino;r.size=st.st_size;r.mtimS=st.st_mtim.tv_sec;r.mtimN=st.st_mtim.tv_nsec;r.ctimS=st.st_ctim.tv_sec;r.ctimN=st.st_ctim.tv_nsec;return true;}
bool sameFile(const Remembered& a,const Remembered& b){return a.dev==b.dev&&a.ino==b.ino&&a.size==b.size&&a.mtimS==b.mtimS&&a.mtimN==b.mtimN&&a.ctimS==b.ctimS&&a.ctimN==b.ctimN;}
void remember(const std::filesystem::path& dir,const QJsonObject& binding,const QJsonObject& state,bool normalized=false)noexcept{try{Remembered r;if(!identity(dir/"features.json",r))return;r.binding=binding;r.state=state;r.notesNormalized=normalized;std::lock_guard lock(rememberedMutex);remembered.erase(dir.string());if(r.size>Store::MaxCacheBytes)return;
 while(!remembered.empty()&&(remembered.size()>=Store::MaxCacheEntries||cachedBytes()+r.size>Store::MaxCacheBytes)){auto oldest=std::min_element(remembered.begin(),remembered.end(),[](const auto& a,const auto& b){return a.second.age<b.second.age;});remembered.erase(oldest);}r.age=++cacheAge;remembered[dir.string()]=std::move(r);}catch(...){}}
bool recall(const std::filesystem::path& dir,const QJsonObject& binding,QJsonObject& state,bool& normalized){Remembered now;bool present=identity(dir/"features.json",now);std::lock_guard lock(rememberedMutex);auto it=remembered.find(dir.string());
 if(!present||it==remembered.end()||!sameFile(it->second,now)||it->second.binding!=binding){++cacheMisses;return false;}++cacheHits;it->second.age=++cacheAge;state=it->second.state;normalized=it->second.notesNormalized;return true;}
QJsonObject read(const std::filesystem::path& p){int fd=::open(p.c_str(),O_RDONLY|O_NOFOLLOW|O_CLOEXEC);require(fd>=0,"product-open");struct stat st{};if(fstat(fd,&st)||!S_ISREG(st.st_mode)||st.st_uid!=getuid()||st.st_nlink!=1||(st.st_mode&0777)!=0600||st.st_size<=0||st.st_size>Store::MaxBytes){close(fd);throw std::runtime_error("product-owner-mode-size");}QByteArray b(st.st_size,Qt::Uninitialized);qsizetype at=0;while(at<b.size()){auto n=::read(fd,b.data()+at,b.size()-at);if(n<0&&errno==EINTR)continue;if(n<=0){close(fd);throw std::runtime_error("product-read");}at+=n;}close(fd);QJsonParseError e;auto d=QJsonDocument::fromJson(b,&e);require(e.error==QJsonParseError::NoError&&d.isObject(),"product-corrupt-json");auto envelope=d.object();require(envelope["payload"].isObject(),"product-corrupt-envelope");auto s=envelope["payload"].toObject();require(envelope["sha256"].toString()==sha256(QJsonDocument(s).toJson(QJsonDocument::Compact)),"product-corrupt-checksum");return s;}
}
void Store::validate(const QJsonObject& s)const{require(s["version"].toInt()==1,"product-migration-unsupported-version");require(s["binding"].toObject()==binding_,"product-document-binding-changed");require(s["annotation"].isObject()&&s["conversations"].isObject()&&s["settings"].isObject()&&s["revision"].isDouble(),"product-feature-schema");for(auto i=s.begin();i!=s.end();++i)require(QStringList{"version","revision","binding","annotation","conversations","settings"}.contains(i.key()),"product-nonfeature-field");auto settings=s["settings"].toObject();if(settings.contains("quietEffects"))require(settings["quietEffects"].isBool(),"product-reveal-setting-schema");auto a=s["annotation"].toObject();if(!a.isEmpty()){for(auto key:{"id","revision","format","pages","layoutId"})require(a[key]==binding_[key],"product-annotation-binding");for(auto i=a.begin();i!=a.end();++i)require(QStringList{"id","revision","format","pages","layoutId","layers","activeLayer","strokes","highlights","notes","undo","redo","undoExpired","modified","layouts"}.contains(i.key()),"product-nonannotation-field");for(auto key:{"layers","strokes","highlights","notes","undo","redo"})require(a[key].isArray(),"product-annotation-arrays");require(a["activeLayer"].isString(),"product-active-layer-schema");if(a.contains("layouts")){require(a["layouts"].isObject()&&a["layouts"].toObject().size()<=256,"product-layout-capacity");for(auto v:a["layouts"].toObject()){auto l=v.toObject();require(l.size()==2&&library::validHash(l["view_id"].toString())&&l["pages"].isDouble()&&l["pages"].toDouble()==l["pages"].toInt(-1)&&l["pages"].toInt()>0&&l["pages"].toInt()<=1000,"product-layout-schema");}}for(auto value:a["notes"].toArray()){auto n=value.toObject();if(n.contains("title"))require(n["title"].isString()&&n["title"].toString().size()<=256&&!n["title"].toString().contains(QChar(0)),"product-note-title-schema");}}}
Store::Store(std::filesystem::path directory,QJsonObject binding):directory_(std::move(directory)),binding_(std::move(binding)){underlay::privateDirectory(directory_);int fd=::open((directory_/"features.lock").c_str(),O_RDWR|O_CREAT|O_NOFOLLOW|O_CLOEXEC,0600);require(fd>=0,"product-lock-open");struct stat st{};if(fstat(fd,&st)||!S_ISREG(st.st_mode)||st.st_uid!=getuid()||st.st_nlink!=1||(st.st_mode&0777)!=0600){close(fd);throw std::runtime_error("product-store-owner-mode");}if(flock(fd,LOCK_EX|LOCK_NB)){close(fd);throw std::runtime_error("product-store-already-open");}lease_=std::shared_ptr<int>(new int(fd),[](int* p){close(*p);delete p;});auto current=directory_/"features.json",prior=directory_/"features.previous.json";if(std::filesystem::exists(current)){if(recall(directory_,binding_,state_,notesNormalized_))return;state_=read(current);validate(state_);remember(directory_,binding_,state_);return;}require(!std::filesystem::exists(prior),"product-current-missing-recovery-required");state_={{"version",1},{"revision",0},{"binding",binding_},{"annotation",QJsonObject{}},{"settings",QJsonObject{}},{"conversations",QJsonObject{}}};commit(state_);remember(directory_,binding_,state_);}
Store::CacheStats Store::cacheStats(){std::lock_guard lock(rememberedMutex);return {unsigned(remembered.size()),cachedBytes(),cacheHits,cacheMisses};}
Store::NotesNormalization Store::notesNormalization()const{std::lock_guard lock(mutex_);return {notesNormalized_,state_.value("revision")};}
void Store::markNotesNormalized(QJsonValue revision)noexcept{try{std::lock_guard lock(mutex_);if(failed_||state_.value("revision")!=revision)return;notesNormalized_=true;remember(directory_,binding_,state_,true);}catch(...){}}
QJsonObject Store::snapshot()const{std::lock_guard lock(mutex_);return state_;}QString Store::error()const{std::lock_guard lock(mutex_);return error_;}bool Store::recovered()const{std::lock_guard lock(mutex_);return recovered_;}void Store::injectFault(Fault f){std::lock_guard lock(mutex_);fault_=f;}
void Store::commit(const QJsonObject& candidate){validate(candidate);auto encoded=encode(candidate);auto fault=fault_;fault_=Fault::None;require(fault!=Fault::BeforeCommit,"injected-product-before-commit");if(std::filesystem::exists(directory_/"features.json"))underlay::atomicFile(directory_/"features.previous.json",encode(state_));underlay::atomicFile(directory_/"features.json",encoded);require(fault!=Fault::AfterCommit,"injected-product-after-durable-commit");}
void Store::transaction(const std::function<void(QJsonObject&)>& change){std::lock_guard lock(mutex_);require(!failed_,"product-reopen-after-durability-error");notesNormalized_=false;auto candidate=state_;change(candidate);candidate["revision"]=state_["revision"].toDouble()+1;try{commit(candidate);state_=candidate;remember(directory_,binding_,state_);error_.clear();recovered_=false;}catch(const std::exception& e){failed_=true;error_=e.what();throw;}}
